public sealed class CreditScheduleSqlTests(SqlFixture fixture):CreditRequirementsSqlBase(fixture),IClassFixture<SqlFixture>,IDisposable
{
    private WebApplicationFactory<Program>? auth;private Task<HttpClient> Staff(string role)=>base.Staff(role,auth??=sql.Factory.WithWebHostBuilder(_=>{}));public void Dispose()=>auth?.Dispose();
    private sealed record Scenario(HttpClient Customer,string Owner,JsonNode Order,JsonNode Quote,string Variant);
    private static string V(JsonNode n,string key)=>CreditCheckoutQuoteQa.Text(n,key);
    private static Task<JsonNode> Read(HttpResponseMessage response)=>CreditScheduleQa.Read(response);
    private async Task<Scenario> Create(HttpClient finance,HttpClient reviewer)
    {
        using var helper=new CreditOrderSqlTests(sql);var s=await helper.Ready(finance,reviewer);var input=new CreditOrderInput(V(s.Quote,"id"),V(s.Quote,"fingerprint"),"Synthetic schedule QA","09100000000",new("IR","تهران","تهران","Synthetic software QA address only","1234567890"),"Software QA only",true,true);var result=await CreditOrderQa.Read(await s.Customer.PostAsJsonAsync("/api/credit-orders/commands/"+Id(),input));return new(s.Customer,s.Owner,result["order"]!,s.Quote,s.Goods.Variant);
    }
    private static string Admin(Scenario s)=>"/api/admin/credit/orders/"+s.Owner+"/"+V(s.Order["summary"]!,"id")+"/schedule";
    private static string Own(Scenario s)=>"/api/credit/orders/"+V(s.Order["summary"]!,"id")+"/schedule";
    private static CreditSchedulePreviewInput Input(Scenario s,string? version=null,string calendar="Persian")=>new(V(s.Order["summary"]!,"version"),version,calendar,DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Asia/Tehran")).DateTime).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture));
    private static SaveCreditScheduleInput Save(CreditSchedulePreviewInput input,JsonNode preview)=>new(input.OrderVersion,input.ScheduleVersion,input.CalendarKind,input.AnchorDate,V(preview,"fingerprint"),true);
    [Fact]public async Task FinancePreviewAndImmutableRevisionsUseOriginalAmountsDatesAndKeepHistoricalCustomerReadsAfterCancellation()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;
        var empty=await Read(await customer.GetAsync(Own(s)));Assert.Null(empty["current"]);Assert.False(empty["canAmend"]!.GetValue<bool>());var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var original=s.Quote["ordinaryQuote"]!;Assert.Equal(V(original,"payableTotalRial"),V(preview["calculation"]!,"payableTotalRial"));Assert.Equal(V(original,"downPaymentRial"),V(preview["calculation"]!,"planDownPaymentRial"));Assert.Equal("12345",V(preview["calculation"]!,"chargesOutsideChequesRial"));Assert.Equal(6,preview["calculation"]!["lines"]!.AsArray().Count);var cmd=Id();var body=Save(input,preview);var first=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+cmd,body));var revision=first["revision"]!;Assert.Equal(1,revision["revision"]!.GetValue<int>());Assert.Equal(preview["calculation"]!.ToJsonString(),revision["calculation"]!.ToJsonString());Assert.False(revision["canPay"]!.GetValue<bool>());Assert.False(revision["canFulfill"]!.GetValue<bool>());
        var changed=Input(s,V(revision,"version"),"Gregorian");var secondPreview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",changed));var second=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),Save(changed,secondPreview)));Assert.Equal(2,second["revision"]!["revision"]!.GetValue<int>());var page=await Read(await customer.GetAsync(Own(s)));Assert.Equal(second["revision"]!.ToJsonString(),page["current"]!.ToJsonString());var history=await Read(await customer.GetAsync(Own(s)+"/history"));Assert.Equal(new[]{2,1},history["items"]!.AsArray().Select(x=>x!["revision"]!.GetValue<int>()));Assert.Equal(revision.ToJsonString(),history["items"]![1]!.ToJsonString());Assert.DoesNotContain(s.Owner,history.ToJsonString(),StringComparison.OrdinalIgnoreCase);
        await CreditOrderQa.Read(await customer.PostAsJsonAsync("/api/orders/v2/"+V(s.Order["summary"]!,"id")+"/cancel",new{version=V(s.Order["summary"]!,"version")}));var closed=await Read(await finance.GetAsync(Admin(s)));Assert.False(closed["canAmend"]!.GetValue<bool>());Assert.Equal("Cancelled",V(closed,"orderState"));var replay=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+cmd,body));Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(revision.ToJsonString(),replay["revision"]!.ToJsonString());using(var denied=await finance.PostAsJsonAsync(Admin(s)+"/preview",Input(s,V(second["revision"]!,"version"))))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
        await using var scope=sql.Factory.Services.CreateAsyncScope();var sp=scope.ServiceProvider;Assert.Equal(0,(await sp.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant)).Reserved);Assert.True(await sp.GetRequiredService<CreditDbContext>().PurchaseScopeUses.AnyAsync(x=>x.OrderId==V(s.Order["summary"]!,"id")));Assert.Equal(OrderState.Cancelled,(await sp.GetRequiredService<SalesDbContext>().Orders.SingleAsync(x=>x.Id==V(s.Order["summary"]!,"id"))).State);
    }
    [Fact]public async Task AuditFailureRollsBackEveryScheduleRowAndConcurrentSameCommandCommitsOnce()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var cmd=Id();var path=Admin(s)+"/commands/"+cmd;var body=Save(input,preview);
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_ScheduleAudit CHECK ([Action]<>'CREDIT_SCHEDULE_SAVE')");
        try{using var failed=await finance.PostAsJsonAsync(path,body);Assert.Equal(HttpStatusCode.Conflict,failed.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_ScheduleAudit");}
        await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();Assert.False(await db.ScheduleRevisions.AnyAsync(x=>x.OrderId==V(s.Order["summary"]!,"id")));Assert.False(await db.ScheduleCommands.AnyAsync(x=>x.CommandId==cmd));}
        var responses=await Task.WhenAll((await Task.WhenAll(finance.PostAsJsonAsync(path,body),finance.PostAsJsonAsync(path,body))).Select(Read));Assert.Single(responses,x=>x["replayed"]!.GetValue<bool>());Assert.Equal(responses[0]["revision"]!.ToJsonString(),responses[1]["revision"]!.ToJsonString());
    }
    [Fact]public async Task StaleVersionsForgedMoneyAndCrossRoleOrOwnerReadsCannotCreateOrExposeASchedule()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var sales=await Staff("SalesManager");var s=await Create(finance,reviewer);using var customer=s.Customer;var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var body=Save(input,preview);
        foreach(var other in new[]{sales,reviewer,customer}){using var denied=await other.GetAsync(Admin(s));Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}var stranger=await Customer();using(var foreign=stranger.Client){using var denied=await foreign.GetAsync(Own(s));Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);}using(var forbidden=await customer.PostAsJsonAsync(Own(s)+"/preview",input))Assert.Contains(forbidden.StatusCode,new[]{HttpStatusCode.NotFound,HttpStatusCode.MethodNotAllowed});using(var query=await finance.GetAsync(Admin(s)+"?ownerId=foreign"))Assert.Equal(HttpStatusCode.BadRequest,query.StatusCode);
        var node=JsonSerializer.SerializeToNode(body,new JsonSerializerOptions(JsonSerializerDefaults.Web))!.AsObject();node["upfrontTotalRial"]="1";using(var forged=await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),node))Assert.Equal(HttpStatusCode.BadRequest,forged.StatusCode);using(var mismatch=await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),body with{CalendarKind="Gregorian"}))Assert.Equal(HttpStatusCode.Conflict,mismatch.StatusCode);
        var created=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),body));using(var stale=await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),body))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);var queue=await Read(await finance.GetAsync("/api/admin/credit/orders"));Assert.Contains(queue["items"]!.AsArray(),x=>V(x!,"orderId")==V(s.Order["summary"]!,"id"));Assert.DoesNotContain("contactPhone",queue.ToJsonString());
    }
    [Fact]public async Task TwoEditsOfOneRevisionCannotOverwriteEachOtherAndCancelNeverAllowsALaterSchedule()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var first=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),Save(input,preview)));var changed=Input(s,V(first["revision"]!,"version"),"Gregorian");var next=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",changed));var edit=Save(changed,next);var replies=await Task.WhenAll(finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),edit),finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),edit));Assert.Single(replies,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(replies,r=>r.StatusCode==HttpStatusCode.Conflict);foreach(var r in replies){if(r.IsSuccessStatusCode)await Read(r);else r.Dispose();}
        var race=await Create(finance,reviewer);using var racing=race.Customer;var raceInput=Input(race);var racePreview=await Read(await finance.PostAsJsonAsync(Admin(race)+"/preview",raceInput));var concurrent=await Task.WhenAll(finance.PostAsJsonAsync(Admin(race)+"/commands/"+Id(),Save(raceInput,racePreview)),racing.PostAsJsonAsync("/api/orders/v2/"+V(race.Order["summary"]!,"id")+"/cancel",new{version=V(race.Order["summary"]!,"version")}));Assert.Equal(HttpStatusCode.OK,concurrent[1].StatusCode);Assert.Contains(concurrent[0].StatusCode,new[]{HttpStatusCode.OK,HttpStatusCode.Conflict});if(concurrent[0].IsSuccessStatusCode){var accepted=await Read(concurrent[0]);var cancelled=await CreditOrderQa.Read(concurrent[1]);await using var scope=sql.Factory.Services.CreateAsyncScope();var order=await scope.ServiceProvider.GetRequiredService<SalesDbContext>().Orders.SingleAsync(x=>x.Id==V(race.Order["summary"]!,"id"));Assert.True(accepted["revision"]!["createdAt"]!.GetValue<DateTimeOffset>()<=order.ChangedAt);}else{concurrent[0].Dispose();concurrent[1].Dispose();}var closed=await Read(await finance.GetAsync(Admin(race)));Assert.False(closed["canAmend"]!.GetValue<bool>());using(var denied=await finance.PostAsJsonAsync(Admin(race)+"/preview",raceInput))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
    }
    private sealed class ScheduleClock(DateTimeOffset at):TimeProvider{public override DateTimeOffset GetUtcNow()=>at;}
    [Fact]public async Task ExpiredOrdersKeepTheirReceiptsAndSqlTamperingFailsClosedInsteadOfRewritingDates()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var cmd=Id();var body=Save(input,preview);var original=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+cmd,body));using var future=sql.Factory.WithWebHostBuilder(b=>b.ConfigureTestServices(services=>services.AddSingleton<TimeProvider>(new ScheduleClock(DateTimeOffset.Parse(V(s.Order["summary"]!,"expiresAt")).AddHours(1)))));using var f=future.CreateClient(new(){HandleCookies=false});foreach(var header in finance.DefaultRequestHeaders)f.DefaultRequestHeaders.TryAddWithoutValidation(header.Key,header.Value);var historical=await Read(await f.PostAsJsonAsync(Admin(s)+"/commands/"+cmd,body));Assert.True(historical["replayed"]!.GetValue<bool>());Assert.Equal(original["revision"]!.ToJsonString(),historical["revision"]!.ToJsonString());using(var expired=await f.PostAsJsonAsync(Admin(s)+"/preview",input))Assert.Equal(HttpStatusCode.Conflict,expired.StatusCode);
        await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<CreditDbContext>().Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ChequeScheduleRevisions] SET [CalendarKind]='Gregorian' WHERE [Id]={V(original["revision"]!,"id")}");using(var corrupt=await customer.GetAsync(Own(s)))Assert.Equal(HttpStatusCode.ServiceUnavailable,corrupt.StatusCode);var oldReceipt=await Read(await finance.GetAsync(Admin(s)+"/commands/"+cmd));Assert.Equal(original["revision"]!.ToJsonString(),oldReceipt["revision"]!.ToJsonString());
    }
    [Fact]public async Task RevisionHistoryPagesTwentyWithoutGapsAndCanonicalCursorsCannotSelectAnotherOrder()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;string? version=null;string? firstId=null;
        for(var i=1;i<=21;i++){var input=Input(s,version,i%2==0?"Gregorian":"Persian");var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var result=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),Save(input,preview)));var revision=result["revision"]!;Assert.Equal(i,revision["revision"]!.GetValue<int>());version=V(revision,"version");firstId??=V(revision,"id");}
        var first=await Read(await customer.GetAsync(Own(s)+"/history"));Assert.Equal(20,first["items"]!.AsArray().Count);Assert.Equal(Enumerable.Range(2,20).Reverse(),first["items"]!.AsArray().Select(x=>x!["revision"]!.GetValue<int>()));Assert.Equal(2,first["nextRevision"]!.GetValue<int>());var last=await Read(await customer.GetAsync(Own(s)+"/history?beforeRevision=2"));Assert.Equal(firstId,V(Assert.Single(last["items"]!.AsArray())!,"id"));Assert.Null(last["nextRevision"]);using(var noncanonical=await finance.GetAsync(Admin(s)+"/history?beforeRevision=01"))Assert.Equal(HttpStatusCode.BadRequest,noncanonical.StatusCode);
    }
    [Fact]public async Task SqlChecksImmutableGuardsAndOwnMigrationDownKeepEveryDatedRevisionAndReceipt()
    {
        using var finance=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Create(finance,reviewer);using var customer=s.Customer;var input=Input(s);var preview=await Read(await finance.PostAsJsonAsync(Admin(s)+"/preview",input));var result=await Read(await finance.PostAsJsonAsync(Admin(s)+"/commands/"+Id(),Save(input,preview)));var id=V(result["revision"]!,"id");
        await using var scope=sql.Factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var wrongMoney=await Assert.ThrowsAsync<SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ChequeScheduleRevisions] SET [UpfrontTotalRial]=[UpfrontTotalRial]+1 WHERE [Id]={id}"));Assert.Equal(547,wrongMoney.Number);var badCase=await Assert.ThrowsAsync<SqlException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE [credit].[ChequeScheduleRevisions] SET [OrderId]={Id()} WHERE [Id]={id}"));Assert.Equal(547,badCase.Number);
        var row=await db.ScheduleRevisions.Include(x=>x.Lines).SingleAsync(x=>x.Id==id);row.PlanName="Forged history";Assert.Equal("credit_schedule_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var line=await db.ScheduleLines.FirstAsync(x=>x.RevisionId==id);db.Remove(line);Assert.Equal("credit_schedule_history_immutable",(await Assert.ThrowsAsync<BusinessException>(()=>db.SaveChangesAsync())).Code);db.ChangeTracker.Clear();var allSource=(await db.Database.GetAppliedMigrationsAsync()).ToArray();await db.GetService<IMigrator>().MigrateAsync("20261027135258_ChequeSchedules");var history=(await db.Database.GetAppliedMigrationsAsync()).ToArray();Assert.EndsWith("_ChequeSchedules",history[^1]);var down=await Assert.ThrowsAsync<SqlException>(()=>db.GetService<IMigrator>().MigrateAsync(history[^2]));Assert.Equal(51000,down.Number);Assert.Equal(history,await db.Database.GetAppliedMigrationsAsync());Assert.True(await db.ScheduleCommands.AnyAsync(x=>x.RevisionId==id));await db.GetService<IMigrator>().MigrateAsync(allSource[^1]);
    }
}
